  3	/**
  4	 * This class collects and provides some statistical data on the state 
  5	 * of a field. It is flexible: it will create and maintain a counter 
  6	 * for any class of object that is found within the field.
  7	 *
  8	 * @version 2016.02.29
  9	 */
 10	public class FieldStats
 11	{
 12	    // Counters for each type of entity (dingo, ant, etc.) in the simulation.
 13	    private HashMap<Class, Counter> counters;
 14	
 15	    /**
 16	     * Construct a FieldStats object.
 17	     */
 18	    public FieldStats() {
 19	        // Set up a collection for counters for each type of animal that
 20	        // we might find
 21	        counters = new HashMap<>();
 22	    }
 23	
 24	    /**
 25	     * Get details of what is in the field.
 26	     * @return A string describing what is in the field.
 27	     */
 28	    public String getPopulationDetails() {
 29	        StringBuffer buffer = new StringBuffer();
 30	        for(Class key : counters.keySet()) {
 31	            Counter info = counters.get(key);
 32	            buffer.append(info.getName());
 33	            buffer.append(": ");
 34	            buffer.append(info.getCount());
 35	            buffer.append(' ');
 36	        }
 37	        return buffer.toString();
 38	    }
 39	
 40	    /**
 41	     * Get details of what is in the field.
 42	     * @return A string describing what is in the field.
 43	     */
 44	    public String getPopulationDetails(Field field) {
 45	        return getPopulationDetails();
 46	    }
 47	    
 48	    /**
 49	     * Reset all counts to zero.
 50	     */
 51	    public void reset() {
 52	        for(Class key : counters.keySet()) {
 53	            Counter count = counters.get(key);
 54	            count.reset();
 55	        }
 56	    }
 57	
 58	    /**
 59	     * Increment the count for one class of occupant.
 60	     * @param animalClass The class of occupant to increment.
 61	     */
 62	    public void incrementCount(Class animalClass) {
 63	        Counter count = counters.get(animalClass);
 64	        if(count == null) {
 65	            // We do not have a counter for this species yet.
 66	            // Create one.
 67	            count = new Counter(animalClass.getName());
 68	            counters.put(animalClass, count);
 69	        }
 70	        count.increment();
 71	    }
 72	
 73	    /**
 74	     * Decrement the count for one class of occupant.
 75	     * @param animalClass The class of occupant to decrement.
 76	     */
 77	    public void decrementCount(Class animalClass) {
 78	        Counter count = counters.get(animalClass);
 79	        if(count != null) {
 80	            count.decrement();
 81	        }
 82	    }
 83	
 84	    /**
 85	     * Record that an occupant has been added to the field.
 86	     */
 87	    public void occupantAdded(FieldOccupant occupant) {
 88	        if(occupant != null) {
 89	            incrementCount(occupant.getClass());
 90	        }
 91	    }
 92	
 93	    /**
 94	     * Record that an occupant has been removed from the field.
 95	     */
 96	    public void occupantRemoved(FieldOccupant occupant) {
 97	        if(occupant != null) {
 98	            decrementCount(occupant.getClass());
 99	        }
100	    }
101	
102	    /**
103	     * Determine whether the simulation is still viable.
104	     * I.e., should it continue to run.
105	     * @return true If there is more than one species alive.
106	     */
107	    public boolean isViable() {
108	        // How many counts are non-zero.
109	        int nonZero = 0;
110	        for(Class key : counters.keySet()) {
111	            Counter info = counters.get(key);
112	            if(info.getCount() > 0) {
113	                nonZero++;
114	            }
115	        }
116	        return nonZero > 1;
117	    }
118	
119	    /**
120	     * Determine whether the simulation is still viable.
121	     * I.e., should it continue to run.
122	     * @return true If there is more than one species alive.
123	     */
124	    public boolean isViable(Field field) {
125	        return isViable();
126	    }
127	}
